<script setup lang="ts">
import AccountingAdminRecordActions from './AccountingAdminRecordActions.vue';
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import {ref,computed,watch} from 'vue';import AccountingSelect from './AccountingSelect.vue';import AccountingDocument from './AccountingDocument.vue';import {useAccountingPermissions} from './permissions';import {requestKey} from './requestKey';
const props=defineProps<{company:number;section:string;csrf?:string}>(),emit=defineEmits<{notice:[message:string]}>(),can=useAccountingPermissions();
const kind=computed(()=>props.section==='purchase-orders'?'purchase':'sale'),group=computed(()=>kind.value==='purchase'?'purchase_orders':'sales_orders');
const rows=ref<any>({data:[],current_page:1,last_page:1}),companies=ref<any[]>([]),editor=ref<any>(null),selected=ref<any>(null),invoice=ref<any>(null),busy=ref(false),loading=ref(false),error=ref(''),search=ref(''),status=ref('');let generation=0;
const seller=computed(()=>companies.value.find(c=>c.id===Number(editor.value?.seller_company_id||selected.value?.seller_company_id))),buyer=computed(()=>companies.value.find(c=>c.id===Number(editor.value?.buyer_company_id||selected.value?.buyer_company_id)));
const money=(n:any)=>Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
const total=computed(()=>editor.value?.lines.reduce((n:number,l:any)=>n+Number(l.quantity||0)*Number(l.rate||0),0)||0),quoted=computed(()=>editor.value?.lines.reduce((n:number,l:any)=>n+Number(l.quantity||0)*Number(l.quoted_rate||0),0)||0);
async function api(path:string,body?:any){const url=new URL('/accounting/api/'+path,location.origin),scope=new URLSearchParams(location.search).get('workspace_group');if(scope)url.searchParams.set('workspace_group',scope);const r=await fetch(url,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(Object.values(v.errors||{}).flat().join(' ')||v.message||'Unable to complete this action.');return v;}
async function load(page=1){const seq=++generation;loading.value=true;try{const params=new URLSearchParams({company_id:String(props.company),kind:kind.value,page:String(page),search:search.value});const party=new URLSearchParams(location.search).get('party_id');if(party)params.set('party_id',party);if(status.value)params.set('status',status.value);const [list,opts]=await Promise.all([api('orders?'+params),api(`orders/options?company_id=${props.company}&kind=${kind.value}`)]);if(seq!==generation)return;rows.value=list;companies.value=opts.companies;error.value='';}catch(e:any){error.value=e.message;}finally{if(seq===generation)loading.value=false;}}
watch(()=>[props.company,props.section],()=>{editor.value=null;selected.value=null;invoice.value=null;search.value='';status.value='';void load();},{immediate:true});
function create(){error.value='';selected.value=null;editor.value={request_key:requestKey(),seller_company_id:kind.value==='sale'?props.company:'',buyer_company_id:kind.value==='purchase'?props.company:'',order_date:new Date().toLocaleDateString('en-CA'),due_date:new Date().toLocaleDateString('en-CA'),terms:'',lines:[{description:'',quantity:'1',quoted_rate:'',rate:''}]};}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function save(){await act(async()=>{const r=await api('orders',editor.value);editor.value=null;emit('notice',r.message);await load();});}
async function transition(action:string){await act(async()=>{const r=await api(`orders/${selected.value.id}/actions`,{company_id:props.company,kind:kind.value,version:selected.value.version,action});emit('notice',r.message);selected.value=null;await load();});}
const catalogue=ref<any[]>([]),catalogueSearch=ref(''),cataloguePage=ref(1),catalogueLast=ref(1),catalogueBusy=ref(false);let catalogueGeneration=0;
async function findCatalogue(page=1){if(!can('items.view')||!editor.value?.seller_company_id)return;const company=Number(editor.value.seller_company_id),token=++catalogueGeneration;catalogueBusy.value=true;try{const d=await api('items?'+new URLSearchParams({company_id:String(company),usage:'sale',search:catalogueSearch.value,page:String(page)}));if(token!==catalogueGeneration||company!==Number(editor.value?.seller_company_id))return;catalogue.value=d.data;cataloguePage.value=d.current_page;catalogueLast.value=d.last_page;}catch(e:any){error.value=e.message;}finally{if(token===catalogueGeneration)catalogueBusy.value=false;}}
watch(()=>editor.value?.seller_company_id,()=>{catalogue.value=[];catalogueSearch.value='';if(editor.value){if(!editor.value.replacement_of)for(const line of editor.value.lines){line.item_id='';}void findCatalogue();}});
function selectCatalogue(line:any){const item=catalogue.value.find(i=>i.id===line.item_id);if(!item)return;line.description=item.description||item.name;line.quoted_rate=item.sale_rate;line.rate=item.sale_rate;}
function accounts(company:any,type:string){return company?.accounts?.filter((a:any)=>type==='income'?a.root_type==='Income':type==='cost'?company.cost_account_ids?.includes(a.id):a.account_type===type&&a.id===(type==='Receivable'?selected.value?.customer_account_id:selected.value?.supplier_account_id))||[];}
function convert(){invoice.value={posting_date:new Date().toLocaleDateString('en-CA'),due_date:selected.value.due_date,receivable_account_id:accounts(seller.value,'Receivable')[0]?.id||'',income_account_id:accounts(seller.value,'income')[0]?.id||'',payable_account_id:accounts(buyer.value,'Payable')[0]?.id||'',cost_account_id:accounts(buyer.value,'cost')[0]?.id||''};}
async function convertSave(){await act(async()=>{const r=await api(`orders/${selected.value.id}/invoices`,{...invoice.value,company_id:props.company,kind:kind.value,version:selected.value.version});emit('notice',r.message);invoice.value=null;selected.value=null;await load();});}
function invoiceHref(row:any){return `${location.pathname}${location.search}${location.search?'&':'?'}entry_id=${row.invoice_id}#${kind.value==='sale'?'sales':'purchases'}`;}
useAccountingLiveRefresh(()=>load(),()=>!editor.value&&!selected.value&&!invoice.value&&!busy.value);
useAccountingAlerts(error);
async function adminRecordChanged(d:any){selected.value=null;invoice.value=null;await load();if(d.context?.form)editor.value=d.context.form;}
</script>
<template><div class="ac-orders"><p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<AccountingDocument v-if="editor" :title="editor.replacement_of?'Correct linked purchase order':'Create linked purchase order'" :busy="busy" @close="editor=null"><form @submit.prevent="save"><p v-if="editor.replacement_of" class="ac-help">The original order and linked invoice changes are committed only after this replacement saves successfully.</p><p class="ac-help">Buyer receives a Purchase Order; seller receives a sales-side order. Both companies must be assigned to you and use the same base currency. Orders do not change ledger balances.</p><div class="ac-form-grid"><label>Seller / service provider<AccountingSelect><select v-model.number="editor.seller_company_id" required :disabled="busy||!!editor.replacement_of||kind==='sale'"><option value="">Select seller</option><option v-for="c in companies.filter(c=>c.id!==Number(editor.buyer_company_id))" :value="c.id">{{c.name}} {{c.currency?'('+c.currency+')':'— books not configured'}}</option></select></AccountingSelect></label><label>Buyer / customer<AccountingSelect><select v-model.number="editor.buyer_company_id" required :disabled="busy||!!editor.replacement_of||kind==='purchase'"><option value="">Select buyer</option><option v-for="c in companies.filter(c=>c.id!==Number(editor.seller_company_id))" :value="c.id">{{c.name}} {{c.currency?'('+c.currency+')':'— books not configured'}}</option></select></AccountingSelect></label><label>Order date<input v-model="editor.order_date" type="date" required></label><label>Delivery / due date<input v-model="editor.due_date" type="date" :min="editor.order_date" required></label></div><div v-if="can('items.view')" class="ac-help"><label>Find seller items<div class="ac-inline-search"><input v-model="catalogueSearch" placeholder="Search item code or name"><button type="button" class="button" :disabled="catalogueBusy||!editor.seller_company_id" @click="findCatalogue()">Find items</button></div></label><div class="ac-pagination"><small>Catalogue page {{cataloguePage}} of {{catalogueLast}}</small><button type="button" class="button" :disabled="catalogueBusy||cataloguePage<=1" @click="findCatalogue(cataloguePage-1)">Previous items</button><button type="button" class="button" :disabled="catalogueBusy||cataloguePage>=catalogueLast" @click="findCatalogue(cataloguePage+1)">Next items</button></div></div><div class="ac-order-scroll"><table><thead><tr><th>Work / item</th><th>Quantity</th><th>Quoted rate</th><th>Agreed rate</th><th>Amount</th><th></th></tr></thead><tbody><tr v-for="(l,index) in editor.lines"><td><AccountingSelect v-if="can('items.view')"><select v-model.number="l.item_id" aria-label="Order item" @change="selectCatalogue(l)"><option value="">Free-text entry</option><option v-for="item in catalogue" :key="item.id" :value="item.id">{{item.code}} - {{item.name}}</option></select></AccountingSelect><input v-model="l.description" required maxlength="250" aria-label="Description"></td><td><input v-model="l.quantity" type="number" min="0.01" step="0.01" required aria-label="Quantity"></td><td><input v-model="l.quoted_rate" type="number" min="0.01" step="0.01" required aria-label="Quoted rate"></td><td><input v-model="l.rate" type="number" min="0.01" step="0.01" required aria-label="Agreed rate" @keydown.enter.prevent="index===editor.lines.length-1&&editor.lines.push({description:'',quantity:'1',quoted_rate:'',rate:''})"></td><td>{{money(Number(l.quantity)*Number(l.rate))}}</td><td><button type="button" class="button" :disabled="editor.lines.length===1" aria-label="Remove line" @click="editor.lines.splice(index,1)">×</button></td></tr></tbody></table></div><button type="button" class="button" @click="editor.lines.push({description:'',quantity:'1',quoted_rate:'',rate:''})">+ Add line</button><label>Terms / notes<textarea v-model="editor.terms" maxlength="2000" rows="3"></textarea></label><div class="ac-help">Quoted: {{money(quoted)}} · Reduction: {{money(quoted-total)}} · <strong>Agreed: {{money(total)}} {{seller?.currency}}</strong></div><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Saving…':'Create both order sides'}}</button></div></form></AccountingDocument>
<AccountingDocument v-else-if="selected" :title="selected.number+' · '+selected.reference" :busy="busy" @close="selected=null;invoice=null"><p class="ac-help">{{selected.status.toUpperCase()}} · No order ledger effect. Customer in seller books; supplier in buyer books.</p><div class="ac-order-details"><p><strong>Seller:</strong> {{seller?.name|| (kind==='purchase'?selected.counterparty:'Current company')}}</p><p><strong>Buyer:</strong> {{buyer?.name|| (kind==='sale'?selected.counterparty:'Current company')}}</p><p>Order: {{selected.order_date}} · Due: {{selected.due_date}}</p></div><div class="ac-order-scroll"><table><thead><tr><th>Description</th><th>Quantity</th><th>Quoted rate</th><th>Agreed rate</th><th>Amount</th></tr></thead><tbody><tr v-for="l in selected.lines"><td>{{l.description}}</td><td>{{l.quantity}}</td><td>{{money(l.quoted_rate)}}</td><td>{{money(l.rate)}}</td><td>{{money(l.amount)}}</td></tr></tbody></table></div><p>Quoted {{money(selected.quoted)}} · Reduction {{money(selected.discount)}} · <strong>Agreed {{money(selected.total)}} {{selected.currency}}</strong></p><p>{{selected.terms}}</p><p v-if="selected.invoice_status">This side’s invoice status: <strong>{{selected.invoice_status}}</strong>. Posting, reversal and payments are handled independently in each company.</p><a v-if="selected.invoice_id" class="button" :href="invoiceHref(selected)">Open invoice</a>
<form v-if="invoice" @submit.prevent="convertSave"><h3>Create paired invoice drafts</h3><p class="ac-help">Pre-tax drafts only. Review applicable taxes in each invoice before approval/posting. This action creates both drafts atomically and does not post them.</p><div class="ac-form-grid"><label>Posting date<input v-model="invoice.posting_date" type="date" required></label><label>Invoice due date<input v-model="invoice.due_date" type="date" :min="invoice.posting_date" required></label><label v-for="spec in [{key:'receivable_account_id',title:'Seller receivable',company:seller,type:'Receivable'},{key:'income_account_id',title:'Seller income',company:seller,type:'income'},{key:'payable_account_id',title:'Buyer payable',company:buyer,type:'Payable'},{key:'cost_account_id',title:'Buyer Cost of Sales account',company:buyer,type:'cost'}]">{{spec.title}}<AccountingSelect><select v-model.number="invoice[spec.key]" required><option value="">Choose account</option><option v-for="a in accounts(spec.company,spec.type)" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label></div><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="invoice=null">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Creating…':'Create both invoice drafts'}}</button></div></form>
<div v-else class="ac-form-actions"><template v-if="selected.can_manage_pair"><button v-if="selected.status==='draft'&&can(group+'.confirm')" class="button primary" :disabled="busy" @click="transition('confirm')">Confirm linked order</button><button v-if="selected.status==='confirmed'&&can(group+'.convert')&&can('sales.create')&&can('purchases.create')" class="button primary" :disabled="busy" @click="convert">Create invoice drafts</button><button v-if="['draft','confirmed'].includes(selected.status)&&can(group+'.cancel')" class="button" :disabled="busy" @click="transition('cancel')">Cancel both order sides</button></template><p v-else class="muted">You can review this company’s order. Changes to both sides require access to both companies.</p></div><AccountingAdminRecordActions :company="company" type="order" :record="selected" :csrf="csrf" :allow-edit="true" @notice="emit('notice',$event)" @changed="adminRecordChanged"/></AccountingDocument>
<template v-else><header class="ac-section-heading"><div><h2>{{kind==='purchase'?'Purchase orders':'Sales-side orders'}}</h2><p class="muted">Linked intercompany agreements, before invoicing and ledger posting.</p></div><button v-if="can('sales_orders.create')&&can('purchase_orders.create')" class="button primary" @click="create">+ Create linked PO</button></header><form class="ac-filters" @submit.prevent="load()"><label>Search orders<input v-model="search" placeholder="Company, reference or notes"></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option v-for="s in ['draft','confirmed','invoiced','cancelled']">{{s}}</option></select></AccountingSelect></label><button class="button" :disabled="loading">{{loading?'Loading…':'Apply filters'}}</button></form><div class="ac-order-scroll"><table><thead><tr><th>Order / link</th><th>{{kind==='sale'?'Customer':'Supplier'}}</th><th>Date</th><th>Status</th><th>Agreed amount</th><th></th></tr></thead><tbody><tr v-for="row in rows.data"><td><strong>{{row.number}}</strong><small>{{row.reference}}</small></td><td>{{row.counterparty}}</td><td>{{row.order_date}}</td><td><span class="ac-badge">{{row.status}}</span></td><td>{{money(row.total)}} {{row.currency}}</td><td><button class="button" @click="selected=row">View order</button></td></tr></tbody></table><p v-if="!loading&&!rows.data.length" class="ac-help">No orders found.</p></div><footer class="ac-order-pagination"><small>Page {{rows.current_page}} of {{rows.last_page}} · {{rows.total||0}} orders</small><div><button class="button" :disabled="loading||rows.current_page===1" @click="load(rows.current_page-1)">Previous</button><button class="button" :disabled="loading||rows.current_page===rows.last_page" @click="load(rows.current_page+1)">Next</button></div></footer></template></div></template>
<style scoped>.ac-orders{min-width:0}.ac-section-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:22px}.ac-order-scroll{overflow:auto;border:1px solid var(--line);border-radius:12px;margin:20px 0}.ac-orders table{width:100%;border-collapse:collapse;font-size:13px;min-width:650px}.ac-orders th,.ac-orders td{padding:13px 12px;text-align:left;border-bottom:1px solid var(--line)}.ac-orders th{font-size:10px;text-transform:uppercase;color:var(--muted)}.ac-orders td small{display:block;color:var(--muted);font-size:10px;margin-top:5px}.ac-orders td input{min-width:100px;max-width:190px;width:100%}.ac-orders label{display:flex;flex-direction:column;gap:8px;margin:12px 0}.ac-order-pagination{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center}.ac-order-pagination .button{margin-left:8px}.ac-order-details{display:flex;flex-wrap:wrap;gap:24px}</style>
